style.css:
@-moz-document domain("userstyles.org") {
/* Change the main background and text colors */
  body,
  .content,
  .header,
  .footer,
  .widget {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }
  
  /* Style links with a distinct color */
  a {
    color: #1e90ff !important;
  }
  
  /* Optional: adjust other elements as needed */
  .navbar,
  .menu,
  .sidebar {
    background-color: #1e1e1e !important;
  }
}
